-- The creators list, brought in step with the team's final sheet of
-- 18 November 2026: 353 creators, 84 of them listed already and 269 new.
--
-- A card is found by its name among the cards the team made (approved,
-- with no owner). A card somebody has claimed is theirs and is left as it
-- is. Nothing here moves a card's status or revision.
--
-- 1. 23 listed cards gain the further links the sheet has for them. A
--    link a card has already is kept as it stands.
UPDATE "creator_cards" AS c
SET "socials" = v."socials" || c."socials", "updated_at" = now()
FROM (VALUES
  ('Aachen Tenzin', '{"youtube":"https://www.youtube.com/@aachentenzin"}'::jsonb),
  ('Ani Yangchen Dolma', '{"youtube":"https://www.youtube.com/@AniYangchenDrolmaOfficial","tiktok":"https://www.tiktok.com/@aniyangchendolma"}'::jsonb),
