JOIN "creator_cards" AS c
  ON c."display_name" = v."display_name" AND c."user_id" IS NULL AND c."status" = 'approved'
 AND c."socials" ->> v."platform" = v."link";
--> statement-breakpoint
-- 4. Each card's own count is its latest reading. A place the sheet has no
--    figure for keeps what the card had.
UPDATE "creator_cards" AS c
SET "youtube_followers" = coalesce(k."youtube", c."youtube_followers"),
    "instagram_followers" = coalesce(k."instagram", c."instagram_followers"),
    "facebook_followers" = coalesce(k."facebook", c."facebook_followers"),
    "tiktok_followers" = coalesce(k."tiktok", c."tiktok_followers")
FROM (
  SELECT "card_id",
    max("followers") FILTER (WHERE "platform" = 'youtube') AS "youtube",
    max("followers") FILTER (WHERE "platform" = 'instagram') AS "instagram",
    max("followers") FILTER (WHERE "platform" = 'facebook') AS "facebook",
    max("followers") FILTER (WHERE "platform" = 'tiktok') AS "tiktok"
  FROM "creator_follower_checks"
  WHERE "month" = '2026-11-01'::date AND "status" = 'ok'
  GROUP BY "card_id"
) AS k
WHERE k."card_id" = c."id";
